    function pin(color, size) {
        return L.divIcon({
            html: '<div style="position:relative;width:'+size+'px;height:'+(size*1.5)+'px;"><div style="position:absolute;top:0;left:50%;width:'+size+'px;height:'+size+'px;border-radius:50% 50% 50% 0;background:'+color+';border:2px solid #fffdf2;box-shadow:0 2px 6px rgba(0,0,0,.3);transform:translateX(-50%) rotate(-45deg);"></div><div style="position:absolute;top:'+(size*0.3)+'px;left:50%;width:'+(size*0.4)+'px;height:'+(size*0.4)+'px;border-radius:50%;background:#fffdf2;transform:translateX(-50%);"></div></div>',
            className: '', iconSize:[size,size*1.5], iconAnchor:[size/2,size*1.5]
        });
    }

    // ── Site detail card wiring (replaces Leaflet popups for kiosk) ──
    const sdcCard = document.getElementById('siteDetailCard');
    const sdcName = document.getElementById('sdcName');
    const sdcTag  = document.getElementById('sdcTag');
    const sdcBody = document.getElementById('sdcBody');
    const sdcClose= document.getElementById('sdcClose');
    var panelScrollInner = document.getElementById('panelScrollInner');

    function openSiteCard(data) {
        if (sdcName) sdcName.textContent = data.name;
        if (sdcTag)  sdcTag.textContent  = data.tag;
        if (sdcBody) sdcBody.textContent  = data.body;
        if (sdcCard) sdcCard.classList.add('open');
        // Dim the scroll content slightly so card reads as foreground
        if (panelScrollInner) panelScrollInner.style.opacity = '.35';
    }

    function closeSiteCard() {
        if (sdcCard) sdcCard.classList.remove('open');
        if (panelScrollInner) panelScrollInner.style.opacity = '';
    }

    if (sdcClose) sdcClose.addEventListener('click', closeSiteCard);
    // Tap dimmed panel content to dismiss
    if (panelScrollInner) panelScrollInner.addEventListener('click', function() {
        if (sdcCard && sdcCard.classList.contains('open')) closeSiteCard();
    });
    // Tap empty map (no layer) → prompt user to look at panel
    map.on('click', function() {
        if (sdcCard && sdcCard.classList.contains('open')) {
            closeSiteCard();
        }
    });

    // ── Wire every layer to the panel detail card ─────────────────
    // Called after all layers + layerInfo are defined (see bottom of file).
    // Using a deferred function so layers exist when this runs.
    function wireLayerClicks() {
        var pairs = [
            { layer: basinLayer,      key: 'basin'       },
            { layer: wildlifeLayer,   key: 'wildlife'    },
            { layer: wildlifeHunting, key: 'hunting'     },
            { layer: nigiriLayerOne,  key: 'nigirione'   },
            { layer: nigiriLayerTwo,  key: 'nigiritwo'   },
            { layer: roadsLayer,      key: 'roads'       },
            { layer: fremontWeirLayer,key: 'fremontweir' },
            { layer: autoTourLayer,   key: 'autotour'    },
            { layer: sacRiverLayer,   key: 'sacriver'    }
        ];
        pairs.forEach(function(p) {
            p.layer.on('click', function(e) {
                L.DomEvent.stopPropagation(e);
                var info = layerInfo[p.key];
                if (info) openSiteCard(info);
            });
        });
    }

    function makeSiteMarker(lat, lng, color, size, data) {
        var marker = L.marker([lat, lng], { icon: pin(color, size), pane: 'paneSites' });
        marker.on('click', function() { openSiteCard(data); });
        return marker;
    }

